application.css:
* {
  box-sizing: border-box;
}

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #18212f;
  background: #edf2f7;
}

body {
  min-height: 100vh;
  margin: 0;
  background: radial-gradient(circle at 10% 0%, #d9f4ef 0, transparent 32%), radial-gradient(circle at 100% 100%, #e4dcff 0, transparent 35%), #f5f7fb;
}

.app-shell {
  width: min(100% - 32px, 680px);
  margin: 0 auto;
  padding: 7vh 0 28px;
}

.todo-card {
  overflow: hidden;
  background: rgba(255, 255, 255, .94);
  border: 1px solid rgba(255, 255, 255, .8);
  border-radius: 24px;
  box-shadow: 0 24px 70px rgba(43, 55, 83, .13);
}

.app-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 38px 40px 28px;
}

.eyebrow {
  margin: 0 0 10px;
  color: #6374d9;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
}

h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 7px; font-size: clamp(30px, 6vw, 42px); letter-spacing: -.045em; }
.subtitle { margin: 0; color: #7d8796; font-size: 14px; }
.header-mark { display: grid; place-items: center; width: 45px; height: 45px; color: white; background: linear-gradient(135deg, #6979e8, #8e6be2); border-radius: 14px; font-size: 25px; font-weight: 700; box-shadow: 0 8px 16px rgba(105, 121, 232, .25); }

.task-form { display: flex; gap: 10px; padding: 0 40px 34px; }
.task-form input { min-width: 0; flex: 1; padding: 14px 17px; color: #18212f; background: #f6f8fb; border: 1px solid #e5e9f0; border-radius: 11px; outline: none; font: inherit; transition: .2s; }
.task-form input:focus { border-color: #7685e7; box-shadow: 0 0 0 4px rgba(118, 133, 231, .13); background: #fff; }
.task-form button { padding: 0 17px; color: #fff; background: #6575dc; border: 0; border-radius: 11px; font: 700 14px inherit; cursor: pointer; transition: .2s; }
.task-form button:hover { background: #5263ce; transform: translateY(-1px); }
.task-form button span { margin-left: 5px; font-size: 18px; vertical-align: -1px; }

.list-heading { display: flex; align-items: center; justify-content: space-between; padding: 0 40px 15px; border-bottom: 1px solid #edf0f4; }
h2 { margin: 0; font-size: 17px; letter-spacing: -.02em; }
.count-pill { padding: 5px 10px; color: #6374d9; background: #eef0ff; border-radius: 20px; font-size: 12px; font-weight: 800; }
.count-label { font-weight: 600; }
.task-list { padding: 8px 40px 18px; }
.task { display: flex; align-items: center; gap: 13px; min-height: 59px; border-bottom: 1px solid #f0f2f5; animation: appear .25s ease-out; }
.task:last-child { border-bottom: 0; }
.complete-button { flex: 0 0 auto; width: 22px; height: 22px; padding: 0; border: 2px solid #c8cfdb; border-radius: 7px; background: white; color: white; cursor: pointer; transition: .2s; }
.complete-button:hover { border-color: #7180df; }
.task[data-completed="true"] .complete-button { border-color: #7180df; background: #7180df; }
.task[data-completed="true"] .complete-button::after { content: "✓"; display: block; font-size: 14px; line-height: 18px; }
.task-text { flex: 1; overflow-wrap: anywhere; color: #344052; font-size: 14px; }
.task[data-completed="true"] .task-text { color: #9ba3b0; text-decoration: line-through; }
.delete-button { padding: 7px; color: #aeb6c2; background: transparent; border: 0; border-radius: 7px; cursor: pointer; font-size: 20px; line-height: 1; opacity: .7; }
.delete-button:hover { color: #ed6b7a; background: #fff0f2; opacity: 1; }
.empty-state { padding: 25px 30px 34px; margin: 0; color: #8893a3; text-align: center; font-size: 14px; line-height: 1.8; }
.empty-state span { color: #b0b7c2; font-size: 12px; }
footer { padding-top: 18px; color: #9aa4b3; text-align: center; font-size: 11px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 520px) { .app-shell { width: min(100% - 20px, 680px); padding-top: 22px; } .app-header { padding: 28px 22px 23px; } .task-form { padding: 0 22px 27px; } .list-heading { padding-inline: 22px; } .task-list { padding-inline: 22px; } .task-form button { padding-inline: 13px; } }

application.javascript:
(function () {
  const form = document.getElementById('task-form');
  const input = document.querySelector('[data-testid="task-input"]');
  const list = document.querySelector('[data-testid="task-list"]');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const empty = document.getElementById('empty-state');
  let tasks = [];

  function render() {
    list.textContent = '';
    tasks.forEach(function (task) {
      const item = document.createElement('div');
      item.className = 'task';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'complete-button';
      toggle.dataset.testid = 'task-complete';
      toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      toggle.addEventListener('click', function () {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', 'Delete task');
      remove.innerHTML = '&times;';
      remove.addEventListener('click', function () {
        tasks = tasks.filter(function (entry) { return entry !== task; });
        render();
      });

      item.append(toggle, text, remove);
      list.appendChild(item);
    });
    count.textContent = tasks.filter(function (task) { return !task.completed; }).length;
    empty.hidden = tasks.length > 0;
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }
    tasks.push({ text: text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
})();
